// MediaPipe 0.10.21, pinned local runtime and models. All inference stays on device.
const VISION_ROOT='/vendor/mediapipe/';
let faceTask=null,objectTask=null,visionLoading=null,visionEnabled=false,visionFrames=[],visionSnapshot=null,visionStartTime=0,visionRAF=0,visionLastTick=0,visionLastVideo=-1,visionCanvas=null,visionPartial=false;
function visionStatus(text){const p=$('#vision-status');if(p)p.textContent=text;document.querySelectorAll('.status-line').forEach(row=>{if(row.textContent.startsWith('Visual detection'))row.querySelector('span').textContent=text})}
async function prepareVision(){if(faceTask)return;if(visionLoading)return visionLoading;visionLoading=(async()=>{visionStatus('Loading local models…');const {FilesetResolver,FaceLandmarker,ObjectDetector}=await import(VISION_ROOT+'vision_bundle.mjs');const files=await FilesetResolver.forVisionTasks(VISION_ROOT+'wasm');const options={runningMode:'VIDEO',numFaces:1,outputFaceBlendshapes:true};try{faceTask=await FaceLandmarker.createFromOptions(files,{...options,baseOptions:{modelAssetPath:VISION_ROOT+'face_landmarker.task',delegate:'GPU'}})}catch{faceTask=await FaceLandmarker.createFromOptions(files,{...options,baseOptions:{modelAssetPath:VISION_ROOT+'face_landmarker.task',delegate:'CPU'}})}try{objectTask=await ObjectDetector.createFromOptions(files,{baseOptions:{modelAssetPath:VISION_ROOT+'efficientdet_lite0.tflite',delegate:'CPU'},runningMode:'VIDEO',scoreThreshold:0.55,maxResults:5})}catch{visionPartial=true}visionStatus(visionPartial?'Face ready · objects unavailable':'Face & objects ready')})().catch(e=>{faceTask?.close();faceTask=null;visionStatus('Unavailable · retry below');throw e}).finally(()=>visionLoading=null);return visionLoading}
function makeVisionCanvas(video){const canvas=document.createElement('canvas');canvas.className='vision-overlay';canvas.setAttribute('aria-hidden','true');video.parentElement.appendChild(canvas);return canvas}
function drawVision(canvas,video,frame){const rect=video.getBoundingClientRect();canvas.width=Math.round(rect.width);canvas.height=Math.round(rect.height);const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);if(!frame||!video.videoWidth)return;const scale=Math.min(canvas.width/video.videoWidth,canvas.height/video.videoHeight),w=video.videoWidth*scale,h=video.videoHeight*scale,x0=(canvas.width-w)/2,y0=(canvas.height-h)/2;ctx.lineWidth=2;ctx.font='12px sans-serif';for(const box of [...frame.faces,...frame.objects]){const x=x0+box.x*w,y=y0+box.y*h;ctx.strokeStyle=box.label==='Face'?'#94e5b6':'#ffd48a';ctx.fillStyle=ctx.strokeStyle;ctx.strokeRect(x,y,box.w*w,box.h*h);const text=box.label;ctx.fillText(text,Math.max(2,x+4),Math.max(14,y-5));for(const point of box.points||[]){ctx.beginPath();ctx.arc(x0+point.x*w,y0+point.y*h,2,0,Math.PI*2);ctx.fill()}}}
function resultFrame(faceResult,objects,video){const faces=(faceResult.faceLandmarks||[]).map(points=>{const xs=points.map(p=>p.x),ys=points.map(p=>p.y),x=Math.max(0,Math.min(...xs)),y=Math.max(0,Math.min(...ys)),right=Math.min(1,Math.max(...xs)),bottom=Math.min(1,Math.max(...ys));return {label:'Face',x,y,w:right-x,h:bottom-y,points:[1,33,263,61,291,152].map(i=>({x:points[i].x,y:points[i].y}))}});return {t:Math.max(0,(performance.now()-visionStartTime)/1000),faces,objects:(objects?.detections||[]).map(d=>({label:d.categories[0]?.categoryName||'Object',x:d.boundingBox.originX/video.videoWidth,y:d.boundingBox.originY/video.videoHeight,w:d.boundingBox.width/video.videoWidth,h:d.boundingBox.height/video.videoHeight}))}}
function visionLoop(now){const video=$('#preview');if(!visionEnabled||view!=='studio'||!video?.srcObject){visionRAF=0;return}if(video.readyState>=2&&now-visionLastTick>=200&&video.currentTime!==visionLastVideo){visionLastTick=now;visionLastVideo=video.currentTime;try{const face=faceTask.detectForVideo(video,now),objects=objectTask?.detectForVideo(video,now),frame=resultFrame(face,objects,video);drawVision(visionCanvas,video,frame);if(recorder?.state==='recording'&&visionFrames.length<18000)visionFrames.push(frame);if(visionFrames.length>=18000)visionPartial=true;const f=frame.faces[0];visionStatus(!f?'No face detected':Math.abs(f.x+f.w/2-.5)<.15?'Face visible · centered':'Face visible · off center')}catch{visionEnabled=false;visionPartial=true;visionStatus('Detection interrupted · retry below');return}}visionRAF=requestAnimationFrame(visionLoop)}
function stopVisionLoop(){cancelAnimationFrame(visionRAF);visionRAF=0;visionLastVideo=-1}
function mountVision(){const video=$('#preview');if(!video)return;visionCanvas=makeVisionCanvas(video);const block=document.createElement('section');block.className='panel vision-controls';block.style.marginTop='18px';block.innerHTML='<h3>Visual practice tools <span class="pill">ON DEVICE</span></h3><p>Optional face landmarks and common-object boxes. Detection samples are saved privately with your recording for synchronized replay. Models can miss objects or lose a face; no identity, emotion, or attention is inferred.</p><button class="secondary" id="enable-vision">Enable visual overlays</button><p id="vision-status" role="status">Not enabled</p>';$('#save-state').after(block);$('#enable-vision').onclick=async()=>{const button=$('#enable-vision');button.disabled=true;try{if(visionEnabled){visionEnabled=false;stopVisionLoop();visionStatus('Disabled');drawVision(visionCanvas,video,null);button.textContent='Enable visual overlays';return}await prepareVision();visionEnabled=true;visionStatus(stream?'Ready · looking for a face':'Ready · enable camera to begin');button.textContent='Disable visual overlays';if(stream&&!visionRAF)visionRAF=requestAnimationFrame(visionLoop)}catch{button.textContent='Retry visual overlays'}finally{button.disabled=false}};visionStatus('Not enabled')}
const renderBeforeVision=render;render=function(v){const recording=recorder?.state==='recording';renderBeforeVision(v);if(recording)return;stopVisionLoop();visionEnabled=false;if(v==='studio'&&view==='studio')mountVision()};
const enableBeforeVision=enable;enable=async function(){await enableBeforeVision();if(stream&&visionEnabled&&!visionRAF)visionRAF=requestAnimationFrame(visionLoop)};
const startBeforeVision=start;start=function(){visionFrames=[];visionSnapshot=null;visionStartTime=performance.now();startBeforeVision();if(recorder?.state==='recording'&&$('#enable-vision'))$('#enable-vision').disabled=true};
const stopBeforeVision=stop;stop=function(){visionSnapshot={version:1,runtime:'0.10.21',status:visionFrames.length?(visionPartial?'partial':'sampled'):'unavailable',intervalMs:200,frames:visionFrames};stopVisionLoop();stopBeforeVision()};
// Save detections before marking the recording ready. Failed uploads retain the snapshot for retry.
const apiBeforeVision=api;api=async function(path,options={}){if(options.method==='PATCH'&&path.startsWith('/rest/v1/sessions?id=eq.')&&JSON.parse(options.body||'{}').status==='ready'&&pending&&visionSnapshot){await apiBeforeVision('/storage/v1/object/recordings/'+pending.user_id+'/'+pending.id+'/visuals.json',{method:'POST',headers:{'Content-Type':'application/json','x-upsert':'true'},body:JSON.stringify(visionSnapshot)})}if(path==='/storage/v1/object/recordings'&&options.method==='DELETE'){const data=JSON.parse(options.body);for(const p of [...data.prefixes])if(p.endsWith('/recording'))data.prefixes.push(p.slice(0,-9)+'visuals.json');options={...options,body:JSON.stringify(data)}}return apiBeforeVision(path,options)};
function frameAt(frames,time){let low=0,high=frames.length-1,found=-1;while(low<=high){const mid=(low+high)>>1;if(frames[mid].t<=time){found=mid;low=mid+1}else high=mid-1}return found>=0&&time-frames[found].t<=.65?frames[found]:null}
const reportBeforeVision=report;report=async function(id){await reportBeforeVision(id);const s=sessions.find(x=>x.id===id),video=$('#playback');if(!s?.cloud||!video)return;const canvas=makeVisionCanvas(video),panel=document.createElement('section');panel.className='panel';panel.style.marginTop='20px';video.parentElement.parentElement.appendChild(panel);panel.innerHTML='<h3>Visual observations</h3><p>Loading saved detections…</p>';try{const response=await api('/storage/v1/object/authenticated/recordings/'+s.user_id+'/'+s.id+'/visuals.json');if(!panel.isConnected)return;const frames=response.frames;if(!Array.isArray(frames)||!frames.length){panel.innerHTML='<h3>Visual observations</h3><p>Unavailable. No visual detection samples were captured for this recording.</p>';return}const visible=frames.filter(f=>f.faces.length),centered=visible.filter(f=>Math.abs(f.faces[0].x+f.faces[0].w/2-.5)<.15);panel.innerHTML=`<h3>Visual observations</h3><p>Face visible in ${visible.length} of ${frames.length} captured samples${visible.length?`; approximately centered in ${Math.round(centered.length/visible.length*100)}% of face-visible samples`:''}. These are sampled detections, not an attention or delivery score.</p><p>${centered.length<visible.length/2?'Try placing your camera at eye level and keeping your face near the middle of the frame.':'Review your framing and leave some room above your head.'}</p><label class="consent"><input type="checkbox" checked id="replay-overlays"> Show saved detection overlays</label><p style="font-size:11px">${response.status==='partial'?'Analysis was partial or interrupted. ':''}Boxes use saved video-relative timestamps. Gaps are shown without boxes. Face direction and movement-based coaching are not assessed.</p><div id="visual-moments"></div>`;document.querySelectorAll('.status-line').forEach(row=>{if(row.textContent.startsWith('Visual observations'))row.querySelector('span').textContent='Saved samples'});const toggle=panel.querySelector('input');let raf=0;function draw(){if(!canvas.isConnected){cancelAnimationFrame(raf);return}drawVision(canvas,video,toggle.checked?frameAt(frames,video.currentTime):null);if(!video.paused&&!video.ended)raf=requestAnimationFrame(draw)}video.addEventListener('play',draw);video.addEventListener('seeked',draw);video.addEventListener('pause',draw);video.addEventListener('loadedmetadata',draw);toggle.onchange=draw;const moments=[];for(let i=1;i<frames.length;i++){if(frames[i-1].faces.length&&!frames[i].faces.length&&(!moments.length||frames[i].t-moments[moments.length-1].t>10))moments.push(frames[i]);if(moments.length===3)break}if(moments.length){const holder=panel.querySelector('#visual-moments');holder.innerHTML='<h4>Review framing changes</h4>';for(const m of moments){const button=document.createElement('button');button.className='text-button';button.textContent=fmt(m.t)+' · Face detection lost';button.onclick=()=>{video.currentTime=m.t;draw()};holder.appendChild(button)}}draw()}catch{panel.innerHTML='<h3>Visual observations</h3><p>Unavailable. Saved visual data could not be loaded for this session.</p>'}};
const style=document.createElement('style');style.textContent='.vision-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.vision-controls p{font-size:11px}.vision-controls h3{font-size:15px}';document.head.appendChild(style);
$('#privacy').onclick=()=>modal('<h2>Your private practice account</h2><p>Videos, transcripts, AI reports, and captured visual detections are saved under your signed-in account in private Supabase storage. Recordings remain until you delete them; automatic cleanup is not active.</p><p>Optional MediaPipe analysis runs on your device. It saves face/object boxes and a small set of landmark points for replay. It does not identify people or infer emotions or attention.</p><p>Browser speech recognition may send audio to your browser provider. With separate consent, OpenAI receives the saved recording for transcription and uses its transcript for content coaching.</p><p>Cloud video limit: 50 MB. OpenAI processing limit: 24 MB. Playback links expire after five minutes; reopen the session to renew. Downloaded copies remain after deleting a cloud session.</p>');
if(view==='studio'&&recorder?.state!=='recording'){mountVision();$('#enable').onclick=enable;$('#record').onclick=start;$('#stop').onclick=stop}
